const generateId = (): string => {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
};

const App = () => {
  const [settings, setSettings] = useState<AudioSettings>({
    volume: 0.7,
    waveform: 'triangle',
    octaveShift: 0,
    sustain: false,
  });

  const [labelMode, setLabelMode] = useState<NoteLabelMode>('japanese');
  const [activeNotes, setActiveNotes] = useState<Set<string>>(new Set());
  const [playedHistory, setPlayedHistory] = useState<PlayedNoteHistory[]>([]);

  // キーボードショートカットの辞書マッピング
  const shortcutMap = useMemo(() => {
    const map = new Map<string, PianoKeyItem>();
    PIANO_KEYS.forEach((key) => {
      map.set(key.keyboardShortcut.toLowerCase(), key);
    });
    return map;
  }, []);

  // 音量変更をオーディオエンジンへ反映
  const handleSettingsChange = useCallback((newSettings: AudioSettings) => {
    setSettings(newSettings);
    setMasterVolume(newSettings.volume);
  }, []);

  // 発音開始ハンドラ
  const handleNoteOn = useCallback(
    (key: PianoKeyItem) => {
      initAudioContext();
      startNote(key, settings);

      setActiveNotes((prev) => {
        const next = new Set(prev);
        next.add(key.id);
        return next;
      });

      // 演奏履歴を最大8件更新
      const displayName =
        labelMode === 'english'
          ? key.noteNameEn
          : labelMode === 'keyboard'
          ? key.keyboardShortcut.toUpperCase()
          : key.noteNameJp;

      setPlayedHistory((prev) => {
        const newEntry: PlayedNoteHistory = {
          id: generateId(),
          name: displayName,
          timestamp: Date.now(),
        };
        const updated = [...prev, newEntry];
        return updated.slice(-8);
      });
    },
    [settings, labelMode]
  );

  // 消音ハンドラ
  const handleNoteOff = useCallback(
    (key: PianoKeyItem) => {
      stopNote(key.id, settings);
      setActiveNotes((prev) => {
        if (!prev.has(key.id)) return prev;
        const next = new Set(prev);
        next.delete(key.id);
        return next;
      });
    },
    [settings]
  );

  // PC物理キーボードのイベントリッスン
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.repeat || e.metaKey || e.ctrlKey || e.altKey) return;
      const keyChar = e.key.toLowerCase();
      const targetKey = shortcutMap.get(keyChar);

      if (targetKey) {
        e.preventDefault();
        handleNoteOn(targetKey);
      }
    };

    const handleKeyUp = (e: KeyboardEvent) => {
      const keyChar = e.key.toLowerCase();
      const targetKey = shortcutMap.get(keyChar);

      if (targetKey) {
        e.preventDefault();
        handleNoteOff(targetKey);
      }
    };

    const handleWindowBlur = () => {
      stopAllNotes();
      setActiveNotes(new Set());
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('blur', handleWindowBlur);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('blur', handleWindowBlur);
    };
  }, [shortcutMap, handleNoteOn, handleNoteOff]);

  return (
    <main className="piano-app">
      {/* ヘッダーエリア */}
      <header className="header">
        <h1>
          <span>Web Piano Studio</span>
          <span className="title-badge">13 Keys</span>
        </h1>
        <div className="played-notes-display">
          <span className="played-notes-label">演奏履歴:</span>
          {playedHistory.length === 0 ? (
            <span className="played-notes-empty">鍵盤を押して音を鳴らそう</span>
          ) : (
            playedHistory.map((item) => (
              <span key={item.id} className="played-badge">
                {item.name}
              </span>
            ))
          )}
        </div>
      </header>

      {/* ガイドバナー */}
      <div className="instruction-banner">
        <span>⌨️ PCキーボードでも演奏可能: 白鍵 [A, S, D, F, G, H, J, K] / 黒鍵 [W, E, T, Y, U]</span>
        <span>🖱️ マウスドラッグ・タッチスライド演奏対応</span>
      </div>

      {/* 鍵盤コンポーネント */}
      <PianoKeyboard
        keys={PIANO_KEYS}
        activeNotes={activeNotes}
        labelMode={labelMode}
        onNoteOn={handleNoteOn}
        onNoteOff={handleNoteOff}
      />

      {/* サウンドコントロールパネル */}
      <ControlPanel
        settings={settings}
        labelMode={labelMode}
        onSettingsChange={handleSettingsChange}
        onLabelModeChange={setLabelMode}
      />
    </main>
  );
};

